using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace Okey101.Core.V4.Tests
{
    /// <summary>
    /// rules.js ↔ C# parity beyond the golden vectors: 72 four-bot matches (6 option sets × 12 seeds) generated by
    /// tools/v4/nunit/gen_parity.js. Every event object of the match and the final match state, in canonical JSON (keys
    /// sorted), must hash the same as in rules.js + bots.js.
    /// </summary>
    public sealed class V4ParityTests
    {
        private const string Fixture = "Packages/com.okey101.core/Tests/Editor/V4/v4-parity.json";

        public static IEnumerable<TestCaseData> Cases()
        {
            var path = Path.Combine(VectorRunner.RepoRoot(), Fixture);
            var j = JObject.Parse(File.ReadAllText(path));
            foreach (JObject c in j["cases"])
            {
                var name = "Parity " + c["opts"].ToString(Formatting.None).Replace("\"", "") + " seed " + (long)c["seed"];
                yield return new TestCaseData(c.ToString(Formatting.None)).SetName(name).SetCategory("V4Parity");
            }
        }

        [TestCaseSource(nameof(Cases))]
        public void BotMatchMatchesRulesJs(string json)
        {
            var c = JObject.Parse(json);
            var opts = VectorRunner.ParseOpts(c["opts"]);
            var seed = (uint)(long)c["seed"];
            var s = G101Rules.NewMatch(opts, seed);
            var events = new List<object>();
            var r = G101Rules.Apply(s, GameAction.StartHand());
            events.AddRange(r.Events.Select(e => (object)e.ToTree()));
            s = r.State;
            int steps = 0, fails = 0;
            for (var guard = 20000; guard-- > 0;)
            {
                if (s.Status == G101Rules.StatusMatchOver) break;
                if (s.Status == G101Rules.StatusHandOver) { r = G101Rules.Apply(s, GameAction.NextHand()); events.AddRange(r.Events.Select(e => (object)e.ToTree())); s = r.State; continue; }
                var seat = s.Hand.Turn.Seat;
                var res = G101Rules.Apply(s, G101Bots.NextAction(s, seat));
                if (!res.Ok) { fails++; res = G101Rules.Apply(s, GameAction.Timeout(seat)); Assert.That(res.Ok, Is.True, "fatal " + res.Error); }
                events.AddRange(res.Events.Select(e => (object)e.ToTree()));
                s = res.State;
                steps++;
            }
            Assert.That(G101Rules.Invariants(s), Is.Empty);
            Assert.That(s.Totals, Is.EqualTo(c["totals"].Select(x => (int)x).ToArray()), "totals");
            Assert.That(steps, Is.EqualTo((int)c["steps"]), "bot actions");
            Assert.That(fails, Is.EqualTo((int)c["fails"]), "rejected bot actions");
            Assert.That(Sha(V4Tree.Canonical(events)), Is.EqualTo((string)c["events"]), "event stream");
            Assert.That(Sha(V4Tree.Canonical(s.ToTree())), Is.EqualTo((string)c["state"]), "final state");
        }

        private static string Sha(string s)
        {
            using (var h = SHA256.Create())
                return string.Concat(h.ComputeHash(Encoding.UTF8.GetBytes(s)).Select(b => b.ToString("x2")));
        }
    }
}
